return $input.all().map((item) => {
  const details = JSON.stringify(item.json.error ?? item.json).toLowerCase();
  const transient = /\b429\b/.test(details) || /\b5\d\d\b/.test(details) || /rate.?limit|too many requests|timeout|timed out|econnreset|etimedout|eai_again|temporar|overload|service unavailable|bad gateway|gateway timeout/.test(details);
  const attempt = Number(item.json.llamaParseRetryAttempt ?? 0) + 1;
  const delays = [10, 30, 90];
  const retryable = transient && attempt < 4;
  return { json: { ...item.json, llamaParseRetryAttempt: attempt, providerRetryable: retryable, providerBackoffSeconds: retryable ? delays[attempt - 1] + Math.floor(Math.random() * 4) : 0 }, binary: item.binary };
});

return $input.all().map((item) => {
  const details = JSON.stringify(item.json.error ?? item.json).toLowerCase();
  const isPermanentQuotaError = /credit.*balance|balance.*too low|insufficient.*credit|plans.*billing|invalid.*api.*key|unauthorized|\b402\b|\b401\b/i.test(details);
  const transient = !isPermanentQuotaError && (/\b429\b/.test(details) || /\b5\d\d\b/.test(details) || /rate.?limit|too many requests|timeout|timed out|econnreset|etimedout|eai_again|temporar|overload|service unavailable|bad gateway|gateway timeout/.test(details));
  const formatFailure = !isPermanentQuotaError && /could not parse|failed to parse|parsing error|model output doesn't fit required format|output_parsing_failure|json.*(?:parse|schema)|expected ',' or '}'|invalid json|structured output|validation error|does not match|zod|schema.*valid/.test(details);
  const attempt = Number(item.json.llmRetryAttempt ?? 0) + 1;
  const unknownFirstAttempt = !isPermanentQuotaError && !transient && !formatFailure && attempt === 1;
  const delays = formatFailure || unknownFirstAttempt ? [2, 6, 15] : [10, 30, 90];
  const retryable = !isPermanentQuotaError && (transient || formatFailure || unknownFirstAttempt) && attempt < 4;
  return {
    json: {
      ...item.json,
      llmRetryAttempt: attempt,
      providerRetryable: retryable,
      providerFailureKind: isPermanentQuotaError ? 'quota_exhausted' : formatFailure ? 'output_format' : transient ? 'provider_transient' : unknownFirstAttempt ? 'unknown_first_attempt' : 'non_retryable',
      providerBackoffSeconds: retryable ? delays[attempt - 1] + Math.floor(Math.random() * 2) : 0
    },
    binary: item.binary
  };
});

// Normalize binary metadata for template files (.xltx -> .xlsx, .dotx -> .docx) before LlamaParse
if ($binary) {
  for (const key of Object.keys($binary)) {
    const entry = $binary[key];
    if (entry && entry.fileName) {
      const ext = String(entry.fileExtension || entry.fileName.split('.').pop() || '').toLowerCase();
      if (ext === 'xltx' || ext === 'xlt' || entry.fileName.toLowerCase().endsWith('.xltx')) {
        entry.fileExtension = 'xlsx';
        entry.fileName = entry.fileName.replace(/\.xltx$/i, '.xlsx').replace(/\.xlt$/i, '.xlsx');
        entry.mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      } else if (ext === 'dotx' || entry.fileName.toLowerCase().endsWith('.dotx')) {
        entry.fileExtension = 'docx';
        entry.fileName = entry.fileName.replace(/\.dotx$/i, '.docx');
        entry.mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
      }
    }
  }
}

const original = $('When Executed by Another Workflow').item.json;
const fileName = String(original.fileName ?? '').toLowerCase();
const pass = (extra = {}) => ({ json: { ...$json, tableStructureStatus: 'not_applicable', tableStructureIssues: '', detectedHeaderRow: 0, columnMapConfidence: 1, tableStructureNeedsReview: false, ...extra }, binary: $binary });
if (!fileName.endsWith('.csv')) return pass();

const binaryEntry = $binary?.data ?? Object.values($binary ?? {})[0];
const base64 = binaryEntry?.data;
if (!base64) return pass({ tableStructureStatus: 'unverified', tableStructureIssues: 'CSV_CONTENT_UNAVAILABLE', columnMapConfidence: 0.2 });

const text = Buffer.from(base64, 'base64').toString('utf8').replace(/^\uFEFF/, '');
const lines = text.split(/\r?\n/).filter((line) => line.trim().length > 0);
if (lines.length < 2) return pass({ tableStructureStatus: 'needs_review', tableStructureIssues: 'CSV_HAS_NO_DATA_ROWS', columnMapConfidence: 0, tableStructureNeedsReview: true });

const delimiters = [',', '\t', ';', '|'];
const delimiter = delimiters
  .map((candidate) => ({ candidate, count: (lines[0].match(new RegExp(candidate === '\t' ? '\\t' : '\\' + candidate, 'g')) ?? []).length }))
  .sort((a, b) => b.count - a.count)[0].candidate;
const parseLine = (line) => {
  const cells = []; let cell = ''; let quoted = false;
  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    if (char === '"') { if (quoted && line[i + 1] === '"') { cell += '"'; i += 1; } else quoted = !quoted; }
    else if (char === delimiter && !quoted) { cells.push(cell.trim()); cell = ''; }
    else cell += char;
  }
  cells.push(cell.trim());
  while (cells.length && !cells[cells.length - 1]) cells.pop();
  return cells;
};
const rows = lines.map(parseLine);
const multiColumnRows = rows.filter((row) => row.length >= 2);
if (multiColumnRows.length < 2) return pass({ tableStructureStatus: 'needs_review', tableStructureIssues: 'CSV_HAS_NO_USABLE_TABULAR_ROWS', columnMapConfidence: 0, tableStructureNeedsReview: true });

const expectedColumns = multiColumnRows[0].length;
const dataRows = multiColumnRows.slice(1);
const mismatched = dataRows.filter((row) => row.length !== expectedColumns).length;
const invalidTokens = dataRows.flat().filter((cell) => /^(#REF!|#VALUE!|#DIV\/0!|#N\/A|TBD|N\/M)$/i.test(cell)).length;
const dataCellCount = Math.max(1, dataRows.flat().length);
const severeColumnDamage = mismatched >= Math.max(3, Math.ceil(dataRows.length * 0.5));
const severeInvalidData = invalidTokens >= Math.max(5, Math.ceil(dataCellCount * 0.5));
const issues = [];
if (dataRows.length < 2) issues.push('LIMITED_DATA_ROWS');
if (mismatched > 0) issues.push('INCONSISTENT_COLUMN_COUNT:' + mismatched);
if (invalidTokens > 0) issues.push('INVALID_OR_PLACEHOLDER_VALUES:' + invalidTokens);
const needsReview = severeColumnDamage || severeInvalidData;
const confidence = Math.max(0.2, Math.min(1, Number((1 - mismatched / Math.max(dataRows.length, 1)).toFixed(2))));
return pass({
  tableStructureStatus: needsReview ? 'needs_review' : issues.length ? 'validated_with_warnings' : 'validated',
  tableStructureIssues: issues.join('; '),
  detectedHeaderRow: 1,
  columnMapConfidence: confidence,
  validatedColumnMap: JSON.stringify(rows[0]),
  tableStructureNeedsReview: needsReview
});

const output = $json.output ?? {};
const facts = Array.isArray(output.financial_facts) ? output.financial_facts : [];
const supported = facts.filter((fact) => fact && fact.status === 'confirmed' && Number.isFinite(Number(fact.normalized_value)));
const metricsList = ['revenue','cogs','gross_profit','ebitda_sde','net_income','cash','debt','total_assets','total_liabilities','equity','working_capital'];
const byMetric = Object.fromEntries(metricsList.map((metric) => [metric, supported.filter((fact) => fact.metric === metric)]));
const warnings = [];
const number = (fact) => Number(fact.normalized_value);
const warning = (value) => { if (!warnings.includes(value)) warnings.push(value); };
const pair = (first, second) => {
  for (const a of byMetric[first]) for (const b of byMetric[second]) {
    if (String(a.period || '').trim() && a.period === b.period && String(a.currency || '').trim() && a.currency === b.currency) return [a, b];
  }
  if (byMetric[first].length && byMetric[second].length) warning('PERIOD_OR_CURRENCY_MISMATCH:' + first + ':' + second);
  return null;
};
const check = (label, actual, expected, inputs) => {
  const tolerance = Math.max(1, Math.abs(expected) * 0.02);
  const difference = actual - expected;
  const withinTolerance = Math.abs(difference) <= tolerance;
  if (!withinTolerance) warning('RECONCILIATION_MISMATCH:' + label);
  return { value: expected, actual, difference, tolerance, withinTolerance, inputs };
};
const rawExpectedValue = (raw) => {
  const text = String(raw ?? '').toLowerCase().replace(/,/g, '');
  if (/%/.test(text)) return null;
  const match = text.match(/([-+]?\d*\.?\d+)\s*([kmb])?\b/);
  if (!match) return null;
  const multiplier = match[2] === 'k' ? 1e3 : match[2] === 'm' ? 1e6 : match[2] === 'b' ? 1e9 : 1;
  return Number(match[1]) * multiplier;
};
for (const fact of supported) {
  const expected = rawExpectedValue(fact.raw_value);
  const actual = number(fact);
  if (expected !== null && expected !== 0 && actual !== 0) {
    const ratio = Math.max(Math.abs(expected / actual), Math.abs(actual / expected));
    if (ratio >= 100) warning('RAW_TO_NORMALIZED_SCALE_MISMATCH:' + fact.metric);
  }
}
for (const metric of metricsList) {
  const groups = {};
  for (const fact of byMetric[metric]) {
    const key = [fact.period || '', fact.currency || ''].join('|');
    (groups[key] ??= []).push(fact);
  }
  for (const samePeriodFacts of Object.values(groups)) {
    const values = samePeriodFacts.map(number).filter((value) => value !== 0);
    if (values.length > 1) {
      const max = Math.max(...values.map(Math.abs));
      const min = Math.min(...values.map(Math.abs));
      if (min > 0 && max / min >= 100) warning('CONFLICTING_FACT_SCALE:' + metric);
    }
  }
}
const metrics = {};
const revenueCogs = pair('revenue', 'cogs');
if (revenueCogs) {
  const [revenue, cogs] = revenueCogs;
  metrics.gross_profit_calculated = { value: number(revenue) - number(cogs), formula: 'revenue - cogs', period: revenue.period, currency: revenue.currency, inputs: { revenue: number(revenue), cogs: number(cogs) } };
  const reported = byMetric.gross_profit.find((fact) => fact.period === revenue.period && fact.currency === revenue.currency);
  if (reported) metrics.gross_profit_check = check('gross_profit', number(reported), metrics.gross_profit_calculated.value, { revenue: number(revenue), cogs: number(cogs), reported_gross_profit: number(reported) });
}
const revenueEbitda = pair('revenue', 'ebitda_sde');
if (revenueEbitda && number(revenueEbitda[0]) !== 0) {
  const [revenue, ebitda] = revenueEbitda;
  const margin = number(ebitda) / number(revenue);
  metrics.ebitda_margin = { value: margin, formula: 'ebitda_sde / revenue', period: revenue.period, currency: revenue.currency, inputs: { revenue: number(revenue), ebitda_sde: number(ebitda) } };
  if (margin > 1 || margin < -0.5) warning('IMPLAUSIBLE_EBITDA_MARGIN');
}
const employee = output.employee_evidence;
const revenueForEmployee = byMetric.revenue.find((fact) => {
  if (!employee || employee.status !== 'confirmed' || !Number.isFinite(Number(employee.count)) || Number(employee.count) === 0) return false;
  const factYear = String(fact.period || '').match(/\b(19|20)\d{2}\b/)?.[0];
  const employeeYear = String(employee.as_of_date || '').match(/\b(19|20)\d{2}\b/)?.[0];
  return factYear && employeeYear && factYear === employeeYear;
});
if (revenueForEmployee) metrics.revenue_per_employee = { value: number(revenueForEmployee) / Number(employee.count), formula: 'revenue / employee_count', period: revenueForEmployee.period, currency: revenueForEmployee.currency, inputs: { revenue: number(revenueForEmployee), employee_count: Number(employee.count) } };
else if (employee?.status === 'confirmed' && byMetric.revenue.length) warning('PERIOD_OR_CURRENCY_MISMATCH:revenue:employee_count');
const assetsLiabilities = pair('total_assets', 'total_liabilities');
if (assetsLiabilities) {
  const [assets, liabilities] = assetsLiabilities;
  metrics.net_assets = { value: number(assets) - number(liabilities), formula: 'total_assets - total_liabilities', period: assets.period, currency: assets.currency, inputs: { total_assets: number(assets), total_liabilities: number(liabilities) } };
  const equity = byMetric.equity.find((fact) => fact.period === assets.period && fact.currency === assets.currency);
  if (equity) metrics.balance_sheet_check = check('balance_sheet', number(assets), number(liabilities) + number(equity), { total_assets: number(assets), total_liabilities: number(liabilities), equity: number(equity) });
}
const debtAssets = pair('debt', 'total_assets');
if (debtAssets && number(debtAssets[1]) !== 0) {
  const [debt, assets] = debtAssets;
  metrics.debt_to_assets = { value: number(debt) / number(assets), formula: 'debt / total_assets', period: debt.period, currency: debt.currency, inputs: { debt: number(debt), total_assets: number(assets) } };
}
const seriousWarnings = warnings.filter((item) => /SCALE_MISMATCH|IMPLAUSIBLE_EBITDA_MARGIN|RECONCILIATION_MISMATCH/.test(item));
const reconciliation = { version: 2, status: seriousWarnings.length ? 'warning' : Object.keys(metrics).length ? 'passed' : 'not_available', warnings, seriousWarnings, metrics, factCount: supported.length };
return { json: { ...$json, financialFacts: supported, reconciliation }, binary: $binary };

const text = String($json.text ?? '');
const characterCount = text.length;
const advisory = characterCount >= 100000
  ? `Large-document advisory: extracted ${Math.round(characterCount / 1000)}k characters. Analysis continued; verify important findings against the source.`
  : '';
return { json: { ...$json, extractedCharacterCount: characterCount, largeDocumentAdvisory: advisory }, binary: $binary };

